<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class PurchaseItem extends Model { protected $fillable=['purchase_id','product_id','quantity','received_quantity','returned_quantity','unit_cost','line_total']; protected $casts=['quantity'=>'decimal:3','received_quantity'=>'decimal:3','returned_quantity'=>'decimal:3','unit_cost'=>'decimal:2','line_total'=>'decimal:2']; public function purchase(){return $this->belongsTo(Purchase::class);} public function product(){return $this->belongsTo(Product::class);} }
